def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_D = opp.count('D')
    my_D = my.count('D')

    # If opponent always defects, defect.
    if opp_D == n:
        return 'D'

    # Last round: always defect.
    if n == 99:
        return 'D'

    # If opponent has never defected despite our defections, they are a pushover.
    if opp_D == 0 and my_D >= 2:
        return 'D'

    # Probe: if opponent has never defected, test them by defecting twice and then cooperating.
    if opp_D == 0:
        if n == 10:
            return 'D'
        if n == 11:
            return 'D'
        if n == 12:
            return 'C'

    # Default: Tit-for-Two-Tats (defect only if opponent defected in the last two rounds).
    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'

    return 'C'
